// n8n Code node "Take the WATFEO Ad Request" in "WATFEO Ads: New Ad" (mode: Run Once for All Items).
// Input: the form ("New WATFEO ad") or another workflow (later: the Telegram bot). Output: { ok, problems, row } for dtj_watfeo_ads.
// The product is fixed (the book "We Are There For Each Other"), so a person only chooses the language, how many ads, and,
// if they want, the angle number from the skill's angle bank (1-58). Everything else comes from the skill watfeo-ugc-ads.
const j = $input.first().json || {};
const pick = (...keys) => { for (const k of keys) { if (j[k] != null && String(j[k]).trim()) return String(j[k]).trim(); } return ''; };
const langs = { english: 'en', en: 'en', hindi: 'hi', hi: 'hi', hinglish: 'hinglish' };
const kinds = { 'full reel': 'reel', reel: 'reel', 'scripts only': 'scripts', scripts: 'scripts', 'prompts only': 'prompts', prompts: 'prompts' };

const language = langs[pick('language', 'Language').toLowerCase()] || '';
const kind = kinds[pick('kind', 'What do you need?').toLowerCase()] || '';
const angleText = pick('angle', 'Angle number (optional, 1-58)');
const angle = angleText ? Number(angleText) : 0;
const count = Number(pick('count', 'How many ads') || '1');
const problems = [];
if (!language) problems.push('language must be English, Hindi or Hinglish');
if (!kind) problems.push('choose: full reel, scripts only or prompts only');
if (angleText && !(Number.isInteger(angle) && angle >= 1 && angle <= 58)) problems.push('the angle must be a number from 1 to 58');
if (!(Number.isInteger(count) && count >= 1 && count <= (kind === 'reel' ? 2 : 5))) {
  problems.push(kind === 'reel' ? 'at most 2 full reels per request' : 'between 1 and 5 per request');
}
const reference = pick('reference', 'Reference reel to copy (optional link)');
if (reference && !/^https:\/\/\S+$/.test(reference) && !/^([A-Za-z]:[\\/]|\/)\S/.test(reference)) problems.push('the reference must be a https link or a path on the laptop');

return [{ json: {
  ok: problems.length === 0,
  problems: problems.join('; '),
  row: {
    submitted_at: new Date().toISOString(),
    status: problems.length ? 'refused' : 'new',
    kind,
    language,
    angle_asked: angle || null,
    count,
    reference,
    notes: pick('notes', 'Notes').slice(0, 2000),
    requested_by: pick('requested_by', 'Your name') || 'form',
    telegram_chat_id: pick('chat_id'),
    raw_json: JSON.stringify(j).slice(0, 8000),
    ad_status: problems.length ? 'refused: ' + problems.join('; ') : 'waiting for Claude Code',
  },
} }];

// n8n Code node "Request for Claude Code: WATFEO Ad" in "WATFEO Ads: New Ad" (mode: Run Once for All Items).
// Inputs: this job (from "Save WATFEO Ad") and every earlier job (from "Load Earlier Ads"), so the request carries the angles the
// whole team has already used. The run pauses at the Wait node after this one; a Claude Code session with the skill
// watfeo-ugc-ads does the task and answers resume_url. CLAUDE.md rule 9: a subscription session is the AI step only while a
// person is on duty.
const job = $('Save WATFEO Ad').first().json;
if (!job || !job.id) throw new Error('No job row (dtj_watfeo_ads id) reached this step');
const resumeUrl = $execution.resumeUrl;
const earlier = $input.all().map((i) => i.json).filter((r) => r && r.id && r.id !== job.id);
const used = [...new Set(earlier.map((r) => Number(r.angle_used)).filter((n) => Number.isInteger(n) && n > 0))].sort((a, b) => a - b);
const folder = 'watfeo-' + job.id;
const langName = { en: 'English', hi: 'Hindi (casual, spoken)', hinglish: 'Hinglish (casual, spoken)' }[job.language] || job.language;
const what = { reel: 'finished reel(s)', scripts: 'script(s) only, in chat and saved', prompts: 'script(s) + every generation prompt, in chat and saved' }[job.kind];

const lines = [
  'WATFEO AD FACTORY - make ' + job.count + ' ' + what + ' for the book "We Are There For Each Other" by Sagar Chudesara.',
  'You are the AI step: a Claude Code session on a DTJ laptop. Nobody has briefed you; the skill has everything.',
  '',
  'JOB',
  '- Job row: id ' + job.id + ' in the n8n data table dtj_watfeo_ads | Asked by: ' + (job.requested_by || '?'),
  '- Language: ' + langName + ' | Count: ' + job.count,
  '- Angle: ' + (job.angle_asked ? '#' + job.angle_asked + ' (asked for; if it is already used, say so and pick the closest fresh one)' : 'your choice: a fresh one'),
  '- Angles the team already used (count them as used): ' + (used.length ? used.join(', ') : 'none recorded in n8n yet'),
  '- Reference reel: ' + (job.reference || 'none: use the skill\'s ad shapes'),
  '- Notes: ' + (job.notes || '(none)'),
  '',
  'DO THIS, IN ORDER',
  '1. In the dtj-agency-automation repo, read CLAUDE.md, then load the skill watfeo-ugc-ads and follow its steps 1-8. Stay on the current branch; do not commit.',
  '2. Work in .work/watfeo/' + folder + '/ (one sub-folder per ad: script.json, prompts.md, and for reels the clips and finals).',
  '3. Every script must pass: python .claude/skills/watfeo-ugc-ads/scripts/lint_script.py <script.json>',
  job.kind === 'reel'
    ? '4. Produce each reel as the skill says (Flow in the signed-in browser, takes checked at 4 fps, sparkle removed, phone look, captions, -14 LUFS, score 80+).'
    : '4. Give the ' + (job.kind === 'scripts' ? 'scripts' : 'scripts and prompts') + ' in chat as the skill says, and save them in the folder.',
  '5. Write .work/watfeo/' + folder + '/result.json: {"reel_status": "reel ready" | "needs a look" | "could not make", "kind": "' + job.kind + '", "final_path": "<' + (job.kind === 'reel' ? 'the final .mp4' : 'the saved .md file') + '>", "angle": <angle number of the first ad>, "note": "<plain words: what was made, the score, what to look at>"}',
  '6. Answer this n8n run, from the repo root, also when nothing could be made:',
  '   python n8n/store-factory/reply.py --resume-url "' + resumeUrl + '" --body .work/watfeo/' + folder + '/result.json',
  '7. Record the angle(s) in the skill (scripts/angles.py use N --ad ' + folder + '), add a dated line to docs/HANDOFF.md, and tell the person on duty in plain words.',
  '',
  'RULES',
  '- Only what the book says (search it with the skill\'s book_search.py). No invented names, numbers, reviews or personal stories.',
  '- The terrace rescue scene is reserved. One setup per ad. The last clip says Read Now / Shop Now / Abhi padhe.',
  '- A new, real-looking creator every time (the skill\'s creators.md); never the generic AI face.',
  '- No password or token in any file or chat. A sign-in or human check = stop and answer "could not make" with "needs a person: <what>".',
  '- Nothing is posted and no ad is started: a person decides.',
];

return [{ json: { claude_code_stage: 'watfeo_ad', resume_url: resumeUrl, instructions: lines.join('\n'),
  request: { job_id: job.id, kind: job.kind, language: job.language, count: job.count, angle_asked: job.angle_asked || null,
             angles_used: used, reference: job.reference || '', notes: job.notes || '', requested_by: job.requested_by || '' },
  job_folder: '.work/watfeo/' + folder } }];

// n8n Code node "Claude Code Reply: WATFEO Ad" in "WATFEO Ads: New Ad" (mode: Run Once for All Items).
// Reads what Claude Code posted to the Wait node (a timeout resumes with no body) and keeps only well-formed values: the same
// rules as n8n/store-factory/reply.py (stage "reel" with "kind"), which refuses a malformed answer before sending it.
const posted = $input.first().json.body;
const b = posted && typeof posted === 'object' && !Array.isArray(posted) ? posted : {};
const allowed = ['reel ready', 'needs a look', 'could not make'];
let status = allowed.includes(b.reel_status) ? b.reel_status : (Object.keys(b).length ? 'reply not understood' : 'timed out (no reply in 3 days)');
const kind = ['reel', 'scripts', 'prompts'].includes(b.kind) ? b.kind : 'reel';
const path = String(b.final_path || '');
const pathOk = (kind === 'reel' ? /\.mp4$/i : /\.(md|json|txt)$/i).test(path) && !/[\r\n]/.test(path);
if (status === 'reel ready' && !pathOk) status = 'reply not understood (no final file)';
const angle = Number.isInteger(b.angle) && b.angle >= 1 && b.angle <= 58 ? b.angle : null;
return [{ json: {
  row_id: $('Request for Claude Code: WATFEO Ad').first().json.request.job_id,
  ad_status: status,
  final_path: pathOk ? path.slice(0, 400) : '',
  angle_used: status === 'reel ready' ? angle : null,
  ad_note: String(b.note || '').slice(0, 1000),
} }];

// n8n Code node "Tell the Requester" in "WATFEO Ads: New Ad" (mode: Run Once for All Items).
// When the ad was asked for from Telegram (the job has a telegram_chat_id), send the result back. Output: [] or one { chat_id, text }.
const job = $('Save WATFEO Ad').first().json || {};
const chat = String(job.telegram_chat_id || '').trim();
if (!chat) return [];
const r = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const what = { reel: 'reel', scripts: 'scripts', prompts: 'scripts and prompts' }[job.kind] || 'ad';
let text;
if (r.ad_status === 'reel ready') {
  text = 'Your WATFEO ' + what + ' ' + (what.endsWith('s') ? 'are' : 'is') + ' ready' + (r.angle_used ? ' (angle #' + r.angle_used + ')' : '')
    + '. File on the laptop:\n' + esc(r.final_path) + (r.ad_note ? '\n\n' + esc(String(r.ad_note).slice(0, 600)) : '')
    + '\nNothing was posted. A person watches it and decides.';
} else {
  text = 'The WATFEO ' + what + ' is not finished (' + esc(r.ad_status || 'no answer') + ')'
    + (r.ad_note ? ': ' + esc(String(r.ad_note).slice(0, 600)) : '.');
}
return [{ json: { chat_id: chat, text } }];
